import express, { type Request, Response, NextFunction } from "express";
import path from "path";
import { registerRoutes } from "./routes";
import simpleRoutes from "./routes-simple";
import { setupVite, serveStatic, log } from "./vite";
import { seedDatabase } from "./seed";

const app = express();

// Trust proxy for deployment environments (Replit, Heroku, etc.)
app.set('trust proxy', true);

// Security headers for production
app.use((req, res, next) => {
  // HTTPS redirect in production
  if (process.env.NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.get('Host')}${req.url}`);
  }

  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // CORS headers for custom domains
  const allowedOrigins = [
    'http://localhost:5173',
    'http://localhost:5000',
    'https://localhost:5000'
  ];

  // Add custom domain if configured
  if (process.env.DOMAIN) {
    allowedOrigins.push(`https://${process.env.DOMAIN}`);
    allowedOrigins.push(`https://www.${process.env.DOMAIN}`);
    allowedOrigins.push(`http://${process.env.DOMAIN}`);
    allowedOrigins.push(`http://www.${process.env.DOMAIN}`);
  }

  // Always allow pollyfortrodas.com.br
  allowedOrigins.push('https://pollyfortrodas.com.br');
  allowedOrigins.push('https://www.pollyfortrodas.com.br');
  allowedOrigins.push('http://pollyfortrodas.com.br');
  allowedOrigins.push('http://www.pollyfortrodas.com.br');

  const origin = req.headers.origin;
  if (origin && allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  } else if (process.env.NODE_ENV === 'development') {
    res.setHeader('Access-Control-Allow-Origin', '*');
  }

  res.setHeader('Access-Control-Allow-Credentials', 'true');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept, Authorization');

  if (req.method === 'OPTIONS') {
    return res.status(200).end();
  }

  next();
});

app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: false, limit: '10mb' }));

// O controle de modo de manutenção é feito no frontend via App.tsx

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  // Try to seed database with initial data, but don't fail if database is not available
  try {
    await seedDatabase();
    log("Database seeded successfully");
  } catch (error) {
    log(`Database seeding failed: ${error instanceof Error ? error.message : String(error)}`);
    log("Application will continue without seeding - database may need manual setup");
  }

  // Add simple routes first (for categories/brands management)
  app.use(simpleRoutes);

  const server = await registerRoutes(app);

  // Setup file serving based on environment
  const isDevelopment = process.env.NODE_ENV !== "production";

  if (isDevelopment) {
    log("Development mode: Using Vite middleware");
    await setupVite(app, server);
  } else {
    log("Production mode: Attempting static file serving");
    try {
      serveStatic(app);
      log("Static files configured for production");
    } catch (error) {
      log(`Static serving failed: ${error instanceof Error ? error.message : String(error)}`);
      log("Production fallback: Using Vite middleware");
      await setupVite(app, server);
    }
  }

  // Add catch-all route for SPA after all other routes
  app.get('*', (req, res, next) => {
    // Skip API routes
    if (req.path.startsWith('/api/')) {
      return res.status(404).json({ message: 'API endpoint not found' });
    }

    // For non-API routes, serve the React app
    log(`SPA Route requested: ${req.path} (isDevelopment: ${isDevelopment})`);

    if (isDevelopment) {
      // In development, let Vite handle it
      return next();
    } else {
      // In production, serve the app properly
      return next();
    }
  });

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    res.status(status).json({ message });
    throw err;
  });

  // ALWAYS serve the app on port 5000
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = 5000;
  server.listen({
    port,
    host: "0.0.0.0",
    reusePort: true,
  }, () => {
    log(`serving on port ${port}`);
  });
})();

